import{_ as n,C as i,o as t,c as l,a2 as r,b as s,w as e,a as p,E as h,a3 as d}from"./chunks/framework.CZW044RH.js";const g="/images/ai-learning-mindset/learning-roadmap.png",f=JSON.parse('{"title":"AI 时代，程序员如何转变学习思维","description":"从被动系统学习，转向按需索取的字典思维。AI 应用开发没那么难，关键是学习方法。","frontmatter":{"title":"AI 时代，程序员如何转变学习思维","description":"从被动系统学习，转向按需索取的字典思维。AI 应用开发没那么难，关键是学习方法。"},"headers":[],"relativePath":"articles/ai-learning-mindset.md","filePath":"articles/ai-learning-mindset.md"}'),c={name:"articles/ai-learning-mindset.md"};function u(A,a,m,b,E,_){const o=i("Mermaid");return t(),l("div",null,[a[1]||(a[1]=r('<h1 id="ai-时代-程序员如何转变学习思维" tabindex="-1">AI 时代，程序员如何转变学习思维 <a class="header-anchor" href="#ai-时代-程序员如何转变学习思维" aria-label="Permalink to &quot;AI 时代，程序员如何转变学习思维&quot;">​</a></h1><blockquote><p>这篇文章写给有开发经验、想转 AI 方向的程序员，也适合零基础刚入行的朋友。核心不是教某个 API 怎么用，而是讲清楚<strong>一种学习的思路</strong>。</p></blockquote><h2 id="一、大模型应用开发-其实没那么难" tabindex="-1">一、大模型应用开发，其实没那么难 <a class="header-anchor" href="#一、大模型应用开发-其实没那么难" aria-label="Permalink to &quot;一、大模型应用开发，其实没那么难&quot;">​</a></h2><p>先给结论：<strong>对于有基础的人来说，AI 应用开发非常简单。</strong></p><p>为什么这么说？</p><p>想想你平时在真实公司里，用 Vue / React / Java 写代码，来来回回用到的其实就那么几个 API。AI 应用开发本质上也是一样的——<strong>它就是在调用第三方的库和接口</strong>。</p><div class="warning custom-block"><p class="custom-block-title">我们不是要成为专家</p><p>我们是要成为<strong>能干活的工程师</strong>。市面上那些岗位——AI 前端、AI Agent、AI 应用开发、AI 全栈、AI 工程师——投简历时可以放心去投，这些都可以是你的方向。</p></div><h2 id="二、按需索取-建立「字典思维」" tabindex="-1">二、按需索取：建立「字典思维」 <a class="header-anchor" href="#二、按需索取-建立「字典思维」" aria-label="Permalink to &quot;二、按需索取：建立「字典思维」&quot;">​</a></h2><p>工作几年之后，学习方式和学生时代完全不一样了。核心思想就四个字：<strong>按需索取</strong>。</p><ul><li><strong>传统方式</strong>：把一套体系从头到尾学一遍，从底层架构学到上层应用。</li><li><strong>AI 时代方式</strong>：<strong>只学工作里真正用到的 API</strong>，够用就行，能应聘、能干活的成本最低。</li></ul><p>就像查字典——用到哪个字，查哪个字，而不是把整本字典背下来。</p><h3 id="学习路线图" tabindex="-1">学习路线图 <a class="header-anchor" href="#学习路线图" aria-label="Permalink to &quot;学习路线图&quot;">​</a></h3><p><img src="'+g+'" alt="AI 学习路线图"></p><p>这张图给出了一个从入门到进阶的完整路线，跟着走即可，不用自己摸索。</p><h2 id="三、计算机科学基础-程序员真正的「根」" tabindex="-1">三、计算机科学基础：程序员真正的「根」 <a class="header-anchor" href="#三、计算机科学基础-程序员真正的「根」" aria-label="Permalink to &quot;三、计算机科学基础：程序员真正的「根」&quot;">​</a></h2><p>整个 AI 学习大纲里，最核心的其实是<strong>计算机科学基础知识</strong>：</p><ul><li>数据结构与算法</li><li>计算机网络</li><li>操作系统原理</li><li>数据库原理</li></ul><p>一个程序员，不管做前端还是后端，这才是根。它训练的是你最值钱的能力：<strong>逻辑思维能力、分析问题和解决问题的能力</strong>。</p><h3 id="语言只是一个工具" tabindex="-1">语言只是一个工具 <a class="header-anchor" href="#语言只是一个工具" aria-label="Permalink to &quot;语言只是一个工具&quot;">​</a></h3><p>不管你现在写什么，语言永远只是一个工具。框架随时会出新版本，它只是一个库。</p><p>比如做 AI 开发要用到 <a href="https://www.langchain.com/" target="_blank" rel="noreferrer">LangChain</a>，以后可能又冒出新的库。那又怎样？你遇到新东西，不要排斥它，点开官网看一眼，把核心点摸清楚就好。</p><p>LangChain 提供了 Python 和 TypeScript 两个版本，对前端程序员来说，TS 版本可以无缝衔接。</p><h3 id="面向官方文档编程的能力" tabindex="-1">面向官方文档编程的能力 <a class="header-anchor" href="#面向官方文档编程的能力" aria-label="Permalink to &quot;面向官方文档编程的能力&quot;">​</a></h3><p>英文不好怎么办？装翻译插件，或者直接丢给 AI 帮你翻译。</p><p>程序员最重要的能力是：<strong>面向官方文档编程</strong>。遇到新东西，第一时间去看官网的 document（文档）。</p><div class="tip custom-block"><p class="custom-block-title">一周掌握一个新工具</p><p>只要你具备底层逻辑思维，加上阅读文档的能力，市面上 99% 的新工具、新语言，你一周之内就能掌握。</p></div><h2 id="四、核心重点-五个方向" tabindex="-1">四、核心重点：五个方向 <a class="header-anchor" href="#四、核心重点-五个方向" aria-label="Permalink to &quot;四、核心重点：五个方向&quot;">​</a></h2><p>无论怎么学，最终要围绕这五个核心：</p>',28)),(t(),s(d,null,{default:e(()=>[h(o,{id:"mermaid-118",class:"mermaid",graph:"mindmap%0A%20%20root((AI%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%3Cbr%2F%3E%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91))%0A%20%20%20%20%E5%85%A5%E9%97%A8%E4%B8%8E%E8%BF%9B%E9%98%B6%0A%20%20%20%20%20%20%E6%A8%A1%E5%9E%8B%E9%83%A8%E7%BD%B2%E4%B8%8E%E8%B0%83%E4%BC%98%0A%20%20%20%20%20%20Prompt%20Engineering%0A%20%20%20%20%20%20%E5%90%91%E9%87%8F%E5%8C%96%E4%B8%8E%20RAG%0A%20%20%20%20%20%20%E6%B5%81%E7%A8%8B%E5%BC%95%E6%93%8E%E7%BC%96%E8%BE%91%E5%99%A8%E5%AE%9E%E6%88%98%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>只要跟着坚持下来，你不只掌握了技能，面试时也能自信地去投 AI 相关岗位。</p><h3 id="用官方脚手架-一天就能搞定" tabindex="-1">用官方脚手架，一天就能搞定 <a class="header-anchor" href="#用官方脚手架-一天就能搞定" aria-label="Permalink to &quot;用官方脚手架，一天就能搞定&quot;">​</a></h3><p>遇到不会的，学它——<strong>只要做过开发，一天就能搞定</strong>：</p><ol><li>用官方脚手架（CLI）把项目跑起来</li><li>然后做业务功能</li><li>业务功能怎么做？<strong>面向官方文档编程</strong></li></ol><p>以 <a href="https://nestjs.com/" target="_blank" rel="noreferrer">NestJS</a> 为例，文档里写得很清楚。你不需要把整个文档读完（有的地方工作 10~20 年都用不到），直接本地跑起来，然后学怎么创建 Controller / Model / 中间件——就是 MVC 那套，会了就能开发。</p><h2 id="五、数据库怎么选" tabindex="-1">五、数据库怎么选 <a class="header-anchor" href="#五、数据库怎么选" aria-label="Permalink to &quot;五、数据库怎么选&quot;">​</a></h2><p>没学过 MySQL 也没关系，现在可以直接用 <strong>PostgreSQL</strong>。ORM 层用一个库（比如 Prisma），就是调用它封装好的方法而已，不用从底层自己造轮子。</p><h2 id="六、ai-应用层开发-核心内容" tabindex="-1">六、AI 应用层开发：核心内容 <a class="header-anchor" href="#六、ai-应用层开发-核心内容" aria-label="Permalink to &quot;六、AI 应用层开发：核心内容&quot;">​</a></h2><p>说白了就是 <a href="https://www.langchain.com/" target="_blank" rel="noreferrer">LangChain</a> 的 API 使用，再加上：</p><ul><li><strong>检索增强（RAG）</strong>：向量化 + 向量数据库的存储与调用</li><li><strong>模型部署与调优</strong></li><li><strong>LangGraph</strong>：流程编排</li></ul><p>整个开发、部署、代码管理、上线，说白了就是<strong>配置文件的使用</strong>，不会就问 AI。</p><p>再一次强调核心：<strong>逻辑思维能力，分析问题、解决问题的能力</strong>。</p><h2 id="七、大部分人在焦虑-而不是在努力" tabindex="-1">七、大部分人在焦虑，而不是在努力 <a class="header-anchor" href="#七、大部分人在焦虑-而不是在努力" aria-label="Permalink to &quot;七、大部分人在焦虑，而不是在努力&quot;">​</a></h2><p>最后送大家两句话：</p><blockquote><p><strong>你不是被 AI 淘汰了，你是被互联网上制造焦虑的人吓到了。</strong></p><p><strong>大部分人在焦虑，而不是在努力。</strong></p></blockquote><p>把焦虑收起来，努力行动起来。</p><p>很多课程一节课 40 分钟、1 个小时，一共一百多节——坚持不下来不是你的错。<strong>10 分钟能讲明白的东西，硬是拖 1 个小时，全是废话，这才是浪费时间。</strong></p><h2 id="八、坚持学下去的技巧" tabindex="-1">八、坚持学下去的技巧 <a class="header-anchor" href="#八、坚持学下去的技巧" aria-label="Permalink to &quot;八、坚持学下去的技巧&quot;">​</a></h2><h3 id="_1-学习坚持不下去-可能是材料的问题" tabindex="-1">1. 学习坚持不下去，可能是材料的问题 <a class="header-anchor" href="#_1-学习坚持不下去-可能是材料的问题" aria-label="Permalink to &quot;1. 学习坚持不下去，可能是材料的问题&quot;">​</a></h3><p>我们总习惯从自己身上找原因：&quot;我学不下去，肯定是我自制力不行。&quot;</p><p>但请换个角度想：<strong>如果内容本身足够好、足够干货，是会驱使人想学下去的。</strong></p><p>很多人网盘里躺着几百 G 的学习资料，B 站收藏了一堆一小时长的视频——真正看完的有几个？这真的不是你的问题，是<strong>材料的问题</strong>。</p><h3 id="_2-主动学习-而不是被动学习" tabindex="-1">2. 主动学习，而不是被动学习 <a class="header-anchor" href="#_2-主动学习-而不是被动学习" aria-label="Permalink to &quot;2. 主动学习，而不是被动学习&quot;">​</a></h3><p>学生时代是被动学习：所有人看同一套教材，不管你想不想看。进入职场后是<strong>主动学习</strong>：你得自己从嘈杂的互联网里，<strong>筛选出有价值、有干货、能促使你主动学下去的好内容</strong>。不管它是收费还是免费，值得就学。</p><h3 id="_3-一定要分享出来" tabindex="-1">3. 一定要分享出来 <a class="header-anchor" href="#_3-一定要分享出来" aria-label="Permalink to &quot;3. 一定要分享出来&quot;">​</a></h3><p>学生时代我们偷偷学，让别人以为你很聪明。但现在，<strong>学习一定要分享出来</strong>：</p><ul><li>发朋友圈</li><li>写公开的笔记</li><li>开源出来</li></ul><p>让别人知道你学习了。这既是监督，也是积累。</p><h3 id="_4-能力要体现出来" tabindex="-1">4. 能力要体现出来 <a class="header-anchor" href="#_4-能力要体现出来" aria-label="Permalink to &quot;4. 能力要体现出来&quot;">​</a></h3><p>在职场里，<strong>你的能力要秀出来</strong>，才能得到更多机会。做过的项目、写过的博客、录过的课，都是你找工作的资本。</p><h3 id="_5-坚持下去-比什么都重要" tabindex="-1">5. 坚持下去，比什么都重要 <a class="header-anchor" href="#_5-坚持下去-比什么都重要" aria-label="Permalink to &quot;5. 坚持下去，比什么都重要&quot;">​</a></h3><p>成年人的学习，唯一的目的就是<strong>能够坚持下去</strong>。找到可持续、能促使你坚持下去的材料和内容，这才最核心。</p><p>下次再觉得&quot;坚持不下去&quot;的时候，先别急着怀疑自己——<strong>也许是材料太垃圾了，换一个就好。</strong></p>',33))])}const I=n(c,[["render",u]]);export{f as __pageData,I as default};
